import test from 'node:test';
import assert from 'node:assert/strict';
import { parseCount } from '../src/parse-count.mjs';

test('accepts canonical non-negative integers', () => {
  assert.equal(parseCount('0'), 0);
  assert.equal(parseCount('12'), 12);
  assert.equal(parseCount(7), 7);
});

test('rejects partial, decimal, negative and empty values', () => {
  assert.equal(parseCount('12x'), null);
  assert.equal(parseCount('3.5'), null);
  assert.equal(parseCount('-1'), null);
  assert.equal(parseCount(''), null);
});

