import test from 'node:test';
import assert from 'node:assert/strict';
import { normalizeTags } from '../src/normalize-tags.mjs';

test('normalizes and deduplicates while preserving order', () => {
  assert.deepEqual(normalizeTags([' Core ', 'core', '', 'News', 'AI']), ['core', 'news', 'ai']);
});

test('rejects invalid shape and bounded-limit violations', () => {
  assert.throws(() => normalizeTags('core'), TypeError);
  assert.throws(() => normalizeTags(Array.from({ length: 9 }, (_, i) => 't' + i)), TypeError);
  assert.throws(() => normalizeTags(['x'.repeat(25)]), TypeError);
});

