export function sumLatencyMs(rows) {
  return (Array.isArray(rows) ? rows : [])
    .map((row) => row?.latencyMs)
    .filter((value) => typeof value === 'number' && Number.isFinite(value))
    .reduce((sum, value) => sum + value, 0);
}

export function sumTokens(rows) {
  return (Array.isArray(rows) ? rows : [])
    .map((row) => row?.tokens)
    .filter((value) => typeof value === 'number' && Number.isFinite(value))
    .reduce((sum, value) => sum + value, 0);
}

