import test from 'node:test';
import assert from 'node:assert/strict';
import * as metrics from '../src/metrics.mjs';

test('preserves latency and token behavior', () => {
  const rows = [
    { latencyMs: 10, tokens: 100 },
    { latencyMs: Number.NaN, tokens: 50 },
    { latencyMs: 5, tokens: 'bad' },
    null,
  ];
  assert.equal(metrics.sumLatencyMs(rows), 15);
  assert.equal(metrics.sumTokens(rows), 150);
});

test('exposes one shared finite-number helper', () => {
  assert.equal(typeof metrics.sumFinite, 'function');
  assert.equal(metrics.sumFinite([{ x: 2 }, { x: Infinity }, { x: 3 }], 'x'), 5);
});
